#pragma once
#include "ksStateScreenActionsTask.h"
#include "ksStatePanelModesTask.h"
#include "ksStateModeTask.h"
#include "ksStateStorageTask.h"
#include "ksStatePartSelectionTask.h"
#include "ksStateBankNavigationTask.h"
