namespace ks {
// Mode selection and routing policy. External requests are typed, complete
// native services; this coordinator never retains an execution-machine frame.
class StatePlaybackModeCoordinator final {
public:
 enum class Kind{Single,Multi,Playback,ResetPlayback,ClearUi,ResetVoices,Routing,ResolveParts,BindPart,ResolveEditPart};
 enum class Component{Action,Reset,Routing,Storage,Resolve,EditPart,Digits};
 enum class Request{None,Ui,SingleProgram,MultiProgram,HeldKeys,ReleaseVoices,Panic};
 struct Input{uint16_t event=0;bool pressed=true;uint8_t part=0;};
 struct Effect{bool read=false,write=false;};
 struct Facts{uint8_t editPart=0,mode=0,active=0,compareActive=0,current=0,held=0,previousMode=0,previousActive=0,available=0,preferred=0,marker=0,savedPart=0,resetPart=0,resetRemaining=0;uint16_t preset=0,program=0;uint32_t currentBase=0,liveBase=0;uint8_t probe=0,probeRemaining=0;bool probed=false,shifted=false,modeRead=false,previousActiveRead=false,partRead=false;};
 struct Edge{Request request=Request::None;unsigned index=0;};
 enum class Operation{Root,Release,ClearEdit,ClearDigits};
 struct Outcome{Kind kind;Input input;Operation operation=Operation::Root;Facts facts{};std::array<Edge,20>children{};unsigned count=0;};
 struct Summary{std::array<std::optional<Outcome>,24>calls{};unsigned count=0,externalCount=0;uint16_t presentation=0;};
 explicit StatePlaybackModeCoordinator(Kind k):StatePlaybackModeCoordinator(k,Input{}){}
 StatePlaybackModeCoordinator(Kind k,Input i):kind_(k),input_(i){summary_.presentation=i.event;push(k,i);}
 Kind kind()const{return kind_;}const Input&input()const{return input_;}const Summary&summary()const{return summary_;}bool complete()const{return !depth_&&request_==Request::None;}bool critical()const{return false;}
 const Effect&effect()const{return effect_;}uint32_t components()const{return components_;}Request request()const{return request_;}unsigned requestIndex()const{return requestIndex_;}uint16_t presentation()const{return summary_.presentation;}
 Component component()const{if(!depth_)return Component::Action;return std::visit([](const auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,Action>)return Component::Action;else if constexpr(std::is_same_v<T,Reset>)return Component::Reset;else if constexpr(std::is_same_v<T,Routing>)return Component::Routing;else if constexpr(std::is_same_v<T,Storage>)return Component::Storage;else if constexpr(std::is_same_v<T,Resolve>)return Component::Resolve;else if constexpr(std::is_same_v<T,EditPart>)return Component::EditPart;else return Component::Digits;},frames_[depth_-1]->task);}
 template<class T>const T*task()const{if constexpr(std::is_same_v<T,Action>||std::is_same_v<T,Reset>||std::is_same_v<T,Routing>||std::is_same_v<T,Storage>||std::is_same_v<T,Resolve>||std::is_same_v<T,EditPart>||std::is_same_v<T,Digits>){if(depth_)return std::get_if<T>(&frames_[depth_-1]->task);}return nullptr;}
 bool resume(uint16_t presentation){if(request_==Request::None)return false;if(request_==Request::Ui||request_==Request::SingleProgram||request_==Request::MultiProgram)summary_.presentation=presentation;request_=Request::None;resumeTop();return true;}
 unsigned nextClocks(int previous=-1)const{if(complete()||request_!=Request::None)return 0;return std::visit([&](const auto&t)->unsigned{using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,Action>)return t.nextClocks(byteClock(actionTarget(t.stage()),previous));else if constexpr(std::is_same_v<T,Reset>)return t.nextClocks(byteClock(resetTarget(t.stage()),previous));else if constexpr(std::is_same_v<T,Resolve>)return t.nextClocks(byteClock(resolveTarget(t.stage()),previous));else if constexpr(std::is_same_v<T,EditPart>)return t.nextClocks(byteClock(0x167d6,previous));else if constexpr(std::is_same_v<T,Digits>)return t.nextClocks(byteClock(0x167fb,previous));else return t.nextClocks();},frames_[depth_-1]->task);}
 template<class R,class W,class Resolver>unsigned advanceBefore(unsigned available,R&&read,W&&write,Resolver&&,int previous=-1){
  const auto cost=nextClocks(previous);if(!cost||available<cost)return 0;effect_={};auto&f=*frames_[depth_-1];auto&facts=summary_.calls[f.outcome]->facts;
  const auto byte=[&](uint32_t raw,unsigned back=0){if(!dataSpan(raw,1))throw std::logic_error("Unsupported evolving mode byte");return uint8_t(read(raw&0xffffff,cost-back));};
  const auto wide=[&](uint32_t raw,unsigned n){if(!dataSpan(raw,n))throw std::logic_error("Unsupported evolving mode span");uint32_t v=0;for(unsigned j=0;j<n;++j){const auto a=(raw+j)&0xffffff;const bool paired=a<0x400000&&!(raw&1);const auto back=3*((n-1-j)/(paired?2:1));v=(v<<8)|uint8_t(read(a,cost-back));}return v;};
  const auto put=[&](uint32_t raw,uint32_t v,unsigned n=1){if(!dataSpan(raw,n))throw std::logic_error("Unsupported evolving mode publication");for(unsigned j=0;j<n;++j)write((raw+j)&0xffffff,uint8_t(v>>(8*(n-1-j))),cost-3*((n-1-j)/2));};
  if(auto*t=std::get_if<Action>(&f.task)){using S=Action::Stage;const auto s=t->stage();
   t->advanceBefore(cost,[&](Action::Read q,uint32_t ref)->uint32_t{switch(q){case Action::Read::EditPart:return facts.editPart=byte(0x16799);case Action::Read::Mode:facts.modeRead=true;return facts.mode=byte(0x167ba);case Action::Read::ActivePart:return facts.active=byte(0x16798);case Action::Read::Current:return facts.current=byte(0x167b8);case Action::Read::Held:return facts.held=byte(0x167b9);case Action::Read::Preset:return facts.preset=uint16_t(wide(0x167ae + ref,2));default:throw std::logic_error("Unexpected mode action observation");}},[&](Action::Write q,uint16_t v){put(actionWrite(q),v,q==Action::Write::Preset?2:1);},byteClock(actionTarget(s),previous));
   if(s==S::SaveSinglePart||s==S::ResetSingleUi||s==S::RefreshSingleRouting||s==S::LoadSingleProgram||s==S::RefreshSingleScreen||s==S::ResetPlaybackContext||s==S::ClearPlaybackEdit||s==S::RefreshPlaybackScreen||s==S::ResetMultiUi||s==S::RefreshMultiRouting||s==S::LoadMultiProgram||s==S::ResolveMultiParts||s==S::RefreshResolvedMulti||s==S::RefreshMultiScreen)effect_.write=true;
   if(s==S::RestoreSinglePart||s==S::ReturnAction||s==S::ReturnEditClear)effect_.read=true;
   if(t->awaitingChild()){switch(s){case S::ResetSingleUi:case S::ResetMultiUi:push(Kind::ClearUi,f.input);break;case S::RefreshSingleRouting:case S::RefreshMultiRouting:case S::RefreshResolvedMulti:push(Kind::Routing,{});break;case S::ResolveMultiParts:push(Kind::ResolveParts,{});break;case S::LoadSingleProgram:ask(Request::SingleProgram);break;case S::LoadMultiProgram:ask(Request::MultiProgram);break;case S::RefreshSingleScreen:case S::RefreshMultiScreen:case S::RefreshPlaybackScreen:ask(Request::Ui);break;case S::ResetPlaybackContext:pushDigits();break;case S::ClearPlaybackEdit:pushAction(Action::Kind::ClearEdit,f.input);break;default:throw std::logic_error("Unexpected mode action child");}}
   else if(t->complete()){if(t->exit()==Action::Exit::ResetVoices){f.tail=true;push(Kind::ResetVoices,{});}else if(t->exit()==Action::Exit::ShowUi){f.tail=true;push(Kind::ResolveEditPart,{});}else if(t->exit()==Action::Exit::Release){f.tail=true;pushAction(Action::Kind::Return,f.input);}else if(t->exit()==Action::Exit::None)finish();else throw std::logic_error("Unexpected mode action tail");}
  }else if(auto*t=std::get_if<Routing>(&f.task)){using S=Routing::Stage;const auto s=t->stage();
   t->advanceBefore(cost,[&](Routing::Read q)->uint32_t{switch(q){case Routing::Read::Mode:facts.modeRead=true;return facts.mode=byte(0x167ba);case Routing::Read::PreviousMode:return facts.previousMode=byte(0x167bb);case Routing::Read::CurrentProgram:return facts.program=uint16_t(wide(0x167ac,2));case Routing::Read::SingleSlot:return facts.program=uint16_t(wide(0x167ae,2));case Routing::Read::SlotProgram:return facts.program=uint16_t(wide(0x167ae + t->slotOffset(),2));case Routing::Read::PartMask:return facts.preferred=byte(0x167d0);case Routing::Read::AuxMask:return facts.held=byte(0x167d1);case Routing::Read::Active:{const auto v=byte(0x16798);if(s==S::ReadCompareActive)facts.compareActive=v;return facts.active=v;}case Routing::Read::PreviousActive:facts.previousActiveRead=true;return facts.previousActive=byte(0x167d4);}throw std::logic_error("Unexpected mode routing observation");},[&](Routing::Write q,uint32_t v){switch(q){case Routing::Write::CurrentBase:facts.currentBase=v;put(0x167bc,v,4);break;case Routing::Write::LiveBase:facts.liveBase=v;put(0x167c0,v,4);break;case Routing::Write::SingleSlot:put(0x167ae,v,2);break;case Routing::Write::CurrentProgram:put(0x167ac,v,2);break;case Routing::Write::SlotProgram:put(0x167ae + t->slotOffset(),v,2);break;default:put(q==Routing::Write::Active?0x16798:q==Routing::Write::PartMask?0x167d2:q==Routing::Write::AuxMask?0x167d3:q==Routing::Write::PreviousMode?0x167bb:0x167d4,v);break;}});
   if(s==S::RetainAddress||s==S::RetainSlot||s==S::RetainMode||s==S::BindPart)effect_.write=true;if(s==S::RestoreMode||s==S::RestoreSlot||s==S::RestoreAddress||s==S::ReturnMode)effect_.read=true;
   if(t->awaitingPart()){Input i;i.part=t->part();push(Kind::BindPart,i);}else if(t->complete())finish();
  }else if(auto*t=std::get_if<Storage>(&f.task)){using S=Storage::Stage;const auto s=t->stage();t->advanceBefore(cost,[](auto)->uint32_t{throw std::logic_error("Unexpected bound-part read");},[&](Storage::Write q,uint32_t v){const auto a=q==Storage::Write::CurrentBase?0x167bc:0x167c0;if(q==Storage::Write::CurrentBase)facts.currentBase=v;else facts.liveBase=v;put(a,v,4);});if(s==S::ReturnPart)effect_.read=true;if(t->complete())finish();
  }else if(auto*t=std::get_if<Resolve>(&f.task)){using S=Resolve::Stage;const auto s=t->stage();t->advanceBefore(cost,[&](Resolve::Read q){const auto v=byte(q==Resolve::Read::Preferred?0x167b8:q==Resolve::Read::Available?0x167d3:0x167d2);if(q==Resolve::Read::Available)facts.available=v;return v;},[&](Resolve::Write q,uint8_t v){facts.preferred=v;put(q==Resolve::Write::Request?0x167d0:0x167b8,v);},byteClock(resolveTarget(s),previous));if(s==S::BindProbeCount){facts.probed=true;facts.probeRemaining=3;}if(s==S::BindProbeMask)facts.probe=facts.available;if(s==S::TestProbeMask)facts.probe&=t->selection();if(s==S::ShiftProbeMask)facts.shifted=true;if(s==S::DecrementProbeCount)--facts.probeRemaining;if(s==S::ReturnResolved)effect_.read=true;if(t->complete()){facts.current=t->selection();finish();}
  }else if(auto*t=std::get_if<EditPart>(&f.task)){using S=EditPart::Stage;const auto s=t->stage();t->advanceBefore(cost,[&](EditPart::Read q,uint32_t ref){const auto v=byte(q==EditPart::Read::Part?0x16799:ref);if(q==EditPart::Read::Part)facts.editPart=v;else facts.marker=v;return v;},[&](EditPart::Write,uint32_t,uint8_t v){put(0x167d6,v);},byteClock(0x167d6,previous));if(s==S::ReturnPartMarker)effect_.read=true;if(t->complete())finish();
  }else if(auto*t=std::get_if<Reset>(&f.task)){using S=Reset::Stage;const auto s=t->stage();t->advanceBefore(cost,[&](Reset::Read q,uint32_t){const auto v=byte(q==Reset::Read::Mode?0x167ba:0x17526);if(q==Reset::Read::Mode)facts.mode=v;else facts.savedPart=v;return v;},[&](Reset::Write q,uint32_t,uint32_t v){put(q==Reset::Write::Mode?0x167ba:0x17526,v);if(q==Reset::Write::Part)facts.resetPart=uint8_t(v);},byteClock(resetTarget(s),previous));if(s==S::SaveResetContext||s==S::SaveResetPart||s==S::ResetPartMidi||s==S::ResetPartVoices||s==S::ResetPartQueue)effect_.write=true;if(s==S::RestoreResetPart||s==S::RestoreResetContext||s==S::ReturnReset)effect_.read=true;if(t->awaitingChild())ask(s==S::ResetPartMidi?Request::HeldKeys:s==S::ResetPartVoices?Request::ReleaseVoices:Request::Panic);else if(t->complete())finish();
  }else{auto&d=std::get<Digits>(f.task);using S=Digits::Stage;const auto s=d.stage();d.advanceBefore(cost,[](auto,auto)->uint32_t{throw std::logic_error("Unexpected clear-digits read");},[&](auto,uint8_t v){put(0x167fb,v);},byteClock(0x167fb,previous));if(s==S::SaveClearDigits)effect_.write=true;if(s==S::RestoreClearDigits||s==S::ReturnClearDigits)effect_.read=true;if(d.complete())finish();}
  return cost;
 }
 static bool dataSpan(uint32_t raw,unsigned n){return StateStoreService::dataSpan(raw,n);}
private:
 using Action=StateScreenActionsTask;using Reset=StatePanelModesTask;using Routing=StateModeTask;using Storage=StateStorageTask;using Resolve=StatePartSelectionTask;using EditPart=StateBankNavigationTask;using Digits=StateProgramBrowseTask;
 using Task=std::variant<Action,Reset,Routing,Storage,Resolve,EditPart,Digits>;
 struct Frame{Task task;Input input;unsigned outcome;bool tail=false;};
 static unsigned byteClock(uint32_t raw,int previous){const auto a=raw&0xffffff;return a<0x400000&&!(previous&1)&&a==(uint32_t(previous)|1u)?0:3;}
 static uint32_t actionWrite(Action::Write q){switch(q){case Action::Write::Mode:return 0x167ba;case Action::Write::Preset:return 0x167ae;case Action::Write::Reload:return 0x167a2;case Action::Write::UiPage:return 0x16790;case Action::Write::Edit:return 0x16784;case Action::Write::Latch:return 0x16792;case Action::Write::Request:return 0x167d0;case Action::Write::HeldRequest:return 0x167d1;case Action::Write::Clear167fb:return 0x167fb;case Action::Write::Clear1679e:return 0x1679e;case Action::Write::Clear167a0:return 0x167a0;case Action::Write::Clear1679f:return 0x1679f;case Action::Write::Clear16784:return 0x16784;case Action::Write::Clear16792:return 0x16792;case Action::Write::Clear167d5:return 0x167d5;case Action::Write::Clear16790:return 0x16790;case Action::Write::Clear16799:return 0x16799;case Action::Write::Clear167a3:return 0x167a3;case Action::Write::Clear16783:return 0x16783;}throw std::logic_error("Unknown mode action publication");}
 static uint32_t actionTarget(Action::Stage s){using S=Action::Stage;switch(s){case S::WriteSinglePreset:return 0x167ae;case S::WriteSingleReload:return 0x167a2;case S::WriteMultiRequest:return 0x167d0;case S::WriteSingleMode:case S::WriteMultiMode:return 0x167ba;case S::WritePlaybackPage:case S::WriteUiPage:return 0x16790;case S::WriteMultiHeld:return 0x167d1;case S::WriteEditActive:return 0x16784;case S::WriteEditLatch:case S::WriteUiLatch:return 0x16792;case S::WriteUiLast:return 0x167fb;case S::WriteUiSpecial:return 0x1679e;case S::WriteUiAuxiliary:return 0x167a0;case S::WriteUiOther:return 0x1679f;case S::WriteUiEdit:return 0x16784;case S::WriteUiMulti:return 0x167d5;case S::WriteUiPart:return 0x16799;case S::WriteUiTranspose:return 0x167a3;case S::WriteUiNote:return 0x16783;default:return 0;}}
 static uint32_t resetTarget(Reset::Stage s){using S=Reset::Stage;return s==S::WriteResetPart||s==S::WriteRestoredPart?0x17526:0x167ba;}
 static uint32_t resolveTarget(Resolve::Stage s){return s==Resolve::Stage::WriteResolvedRequest?0x167d0:0x167b8;}
 void edge(Request r,unsigned index){if(!depth_)return;auto&o=*summary_.calls[frames_[depth_-1]->outcome];if(o.count==o.children.size())throw std::logic_error("Mode outcome child capacity");o.children[o.count++]={r,index};}
 template<class T>void start(T t,Kind k,Input i,Operation op=Operation::Root){if(depth_==frames_.size()||summary_.count==summary_.calls.size())throw std::logic_error("Mode semantic capacity");const auto n=summary_.count++;edge(Request::None,n);summary_.calls[n].emplace(Outcome{k,i,op});frames_[depth_++].emplace(Frame{Task{std::move(t)},i,n});components_|=1u<<unsigned(component());}
 void push(Kind k,Input i){switch(k){case Kind::Single:pushAction(Action::Kind::Single,i);break;case Kind::Multi:pushAction(Action::Kind::Multi,i);break;case Kind::Playback:pushAction(Action::Kind::Playback,i);break;case Kind::ResetPlayback:pushAction(Action::Kind::ResetPlayback,i);break;case Kind::ClearUi:pushAction(Action::Kind::ClearUi,i);break;case Kind::ResetVoices:start(Reset(Reset::Kind::ResetVoices),k,i);break;case Kind::Routing:start(Routing{},k,i);break;case Kind::ResolveParts:start(Resolve(Resolve::Kind::Resolve),k,i);break;case Kind::BindPart:start(Storage(Storage::Kind::BindPart,i.part),k,i);break;case Kind::ResolveEditPart:start(EditPart(EditPart::Kind::Resolve),k,i);break;}}
 void pushAction(Action::Kind k,Input i){const auto kind=k==Action::Kind::Single?Kind::Single:k==Action::Kind::Multi?Kind::Multi:k==Action::Kind::Playback?Kind::Playback:k==Action::Kind::ResetPlayback?Kind::ResetPlayback:Kind::ClearUi;start(Action(k,i.event,i.pressed),kind,i,k==Action::Kind::Return?Operation::Release:k==Action::Kind::ClearEdit?Operation::ClearEdit:Operation::Root);}
 void pushDigits(){start(Digits(Digits::Kind::Clear),Kind::ResetPlayback,{},Operation::ClearDigits);}
 void ask(Request r){if(request_!=Request::None)throw std::logic_error("Mode request already owned");request_=r;requestIndex_=summary_.externalCount++;edge(r,requestIndex_);}
 void finish(){if(!depth_)throw std::logic_error("Invalid mode completion");frames_[--depth_].reset();resumeTop();}
 void resumeTop(){if(!depth_)return;auto&f=*frames_[depth_-1];if(f.tail){finish();return;}std::visit([](auto&t){using T=std::decay_t<decltype(t)>;if constexpr(std::is_same_v<T,Routing>)t.resumePart();else if constexpr(std::is_same_v<T,Storage>)t.resumePart();else if constexpr(std::is_same_v<T,Action>)t.resumeChild(false);else if constexpr(std::is_same_v<T,Reset>)t.resumeChild(false);else if constexpr(std::is_same_v<T,EditPart>)t.resumeChild(0);else if constexpr(std::is_same_v<T,Resolve>)t.resumeChild();},f.task);}
 Kind kind_;Input input_;Summary summary_{};Effect effect_{};std::array<std::optional<Frame>,6>frames_{};unsigned depth_=0,requestIndex_=0;uint32_t components_=0;Request request_=Request::None;
};
}
